INSERT INTO `books` (`books_id`, `Myimage`, `title`, `slug`, `Mysubject`, `Mydescription`, `keywords`, `Author`, `autre`, `the_type`, `dir`, `language`, `visibility_status`, `updated_at`, `created_at`, `gender`, `min_age`, `max_age`, `educational_level`) VALUES
(2, 'tamusni_turari.webp', 'ⵜⴰⵎⵓⵙⵏⵉ ⵜⵓⵔⴰⵔⵉ - مجلة أمازيغية للأطفال', 'ⵜⴰⵎⵓⵙⵏⵉ_ⵜⵓⵔⴰⵔⵉ_مجلة_أمازيغية_للأطفال', '<p>    ⵜⴰⵎⵓⵙⵏⵉ ⵜⵓⵔⴰⵔⵉ : هي مجلة للصغار  تهدف لتشجيع الأطفال على تعلم الأمازيغية بأحرف تيفيناغ ، حيث تضم ألعاب ممتعة تعتمد على أحرف تيفيناغ سهلة وصور توضيحية جميلة، سيحب الأطفال هده المجلة بالتأكيد لأنها صممت خصيصا لأجلهم ولأجل تنمية معارفهم ودكائهم .</p>				', 'ⵜⴰⵎⵓⵙⵏⵉ ⵜⵓⵔⴰⵔⵉ هي مجلة للصغار  تهدف لتشجيع الأطفال على تعلم الأمازيغية بأحرف تيفيناغ ، حيث تضم ألعاب ممتعة تعتمد على أحرف تيفيناغ سهلة وصور توضيحية جميلة، سيحب الأطفال هده المجلة بالتأكيد لأنها صممت خصيصا لأجلهم ولأجل تنمية معارفهم ودكائهم.', 'مجلة أمازيغية,tamusni turari,ⵜⴰⵎⵓⵙⵏⵉ ⵜⵓⵔⴰⵔⵉ,مجلة للأطفال,مكتبة تيفيناغ', 'حميد بعلوان', 'tamusni_turari.pdf', 'مجلات, الأمازيغية', 'rtl', 'amz', 'public', '2025-09-08 23:08:14', '2024-09-09 23:00:00', 'all', 2, 75, '0'),
(3, 'tifinagh.webp', 'تيفيناغ في أربع خطوات', 'تيفيناغ_في_أربع_خطوات', '    <p> هدا الكتاب هو محاولة لتبسيط اللغة الأمازيغية لمن بدأوا للتوفي تعلمها من الصفر، ويضم بين طياته صور توضيحية للمساعدة على الفهم وكدا للاستئاس، كما استعمل المؤلف أيضا أدوات عدة وألوان مختلفة للمساعدة وتسهيل القراءة على من ليست لديهم أية خلفية معرفية في اللغة الأمازيغية.\r\n</p>\r\n<i>نتمنى لكم قراءة ممتعة</i>', ' هدا الكتاب هو محاولة لتبسيط اللغة الأمازيغية لمن بدأوا للتوفي تعلمها من الصفر، ويضم بين طياته صور توضيحية للمساعدة على الفهم وكدا للاستئاس، كما استعمل المؤلف أيضا أدوات عدة وألوان مختلفة للمساعدة وتسهيل القراءة على من ليست لديهم أية خلفية معرفية في اللغة الأمازيغية', ' هدا الكتاب هو محاولة لتبسيط اللغة الأمازيغية لمن بدأوا للتوفي تعلمها من الصفر، ويضم بين طياته صور توضيحية للمساعدة على الفهم وكدا للاستئاس، كما استعمل المؤلف أيضا أدوات عدة وألوان مختلفة للمساعدة وتسهيل القراءة على من ليست لديهم أية خلفية معرفية في اللغة الأمازيغية', 'حميد بعلوان', 'تيفيناغ_في_أربع_خطوات.pdf', 'الأمازيغية', 'rtl', 'amz', 'public', '2025-09-08 23:11:17', '2024-08-20 23:00:00', 'all', 9, 75, '1'),
(4, 'agldun.webp', 'ⴰⴳⵍⴷⵓⵏ ⴰⵎⵥⵥⴰⵏ', 'ⴰⴳⵍⴷⵓⵏ_ⴰⵎⵥⵥⴰⵏ', '<p>    هنا يمكنك تحميل قصة : ⴰⴳⵍⴷⵓⵏ ⴰⵎⵥⵥⴰⵏ .\r\n                                  </p>\r\n                        نتمنى لكم قراءة ممتعة. ', 'هنا يمكنك تحميل قصة : ⴰⴳⵍⴷⵓⵏ ⴰⵎⵥⵥⴰⵏ \r\nنتمنى لكم قراءة ممتعة.                                                                                    ', 'هنا يمكنك تحميل قصة : ⴰⴳⵍⴷⵓⵏ ⴰⵎⵥⵥⴰⵏ                                                      ', '', 'agldun.pdf', 'قصص و روايات, الأمازيغية', 'rtl', 'amz', 'public', '2025-09-08 23:08:14', '2024-08-20 23:00:00', 'all', 2, 75, '0'),
(5, 'augustin.webp', 'الاعترافات - القديس أوغسطين', 'الاعترافات_القديس_أوغسطين', 'الاعترافات أو اعترافاتي هو مجموعة من مؤلفات القديس أوغسطين يحكي فيها عن حياته ويبين فيها كيف تعرف على الله ليتبنى بعد دلك للفكر المسيحي.', 'الاعترافات أو اعترافاتي هو مجموعة من مؤلفات القديس أوغسطين يحكي فيها عن حياته ويبين فيها كيف تعرف على الله ليتبنى بعد دلك للفكر المسيحي.', 'الاعترافات أو اعترافاتي هو مجموعة من مؤلفات القديس أوغسطين يحكي فيها عن حياته ويبين فيها كيف تعرف على الله ليتبنى بعد دلك للفكر المسيحي.', '', 'i3tirafat.pdf', 'قصص و روايات', 'rtl', 'amz', 'public', '2025-09-08 23:11:17', '2024-08-20 23:00:00', 'all', 15, 75, '10'),
(8, 'sidi_hamou_talb.webp', 'الشعر الأمازيغي المنسوب - لسيدي حمو طالب', 'الشعر_الأمازيغي_المنسوب_لسيدي_حمو_طالب', '<p>    في هدا المؤلف ستجدون مجموعة من القصائد الشعرية الأمازيغية المنسوبة للشاعر المعروف بسيدي حمو طالب، والتي لا يزال العديد من سكان منطقة سوس يتغنون بها. </p>', '  في هدا المؤلف ستجدون مجموعة من القصائد الشعرية الأمازيغية المنسوبة للشاعر المعروف بسيدي حمو طالب، والتي لا يزال العديد من سكان منطقة سوس يتغنون بها ', '  في هدا المؤلف ستجدون مجموعة من القصائد الشعرية الأمازيغية المنسوبة للشاعر المعروف بسيدي حمو طالب، والتي لا يزال العديد من سكان منطقة سوس يتغنون بها ', '', 'sidi-hamou-talb.pdf', 'قصائد شعرية, الأمازيغية', 'rtl', 'amz', 'public', '2025-09-08 23:11:17', '2024-09-09 23:00:00', 'all', 14, 75, '3'),
(9, 'tamusni_2.webp', 'مجلة المعرفة الجزء 2 - ⵜⴰⵎⵓⵙⵏⵉ', 'مجلة_المعرفة_الجزء_2_ⵜⴰⵎⵓⵙⵏⵉ', '<p>    مجلة المعرفة تصدر من ليبيا وتهدف لتعليم الأمازيغية للأطفال وتشجيعهم على قراءتها. </p>                                 ', 'مجلة المعرفة تصدر من ليبيا وتهدف لتعليم الأمازيغية للأطفال وتشجيعهم على قراءتها                                  ', 'مجلة المعرفة تصدر من ليبيا وتهدف لتعليم الأمازيغية للأطفال وتشجيعهم على قراءتها                                  ', '', 'tamusni_2.pdf', 'مجلات, الأمازيغية', 'rtl', 'amz', 'public', '2025-09-08 23:08:14', '2024-09-09 23:00:00', 'all', 2, 75, '0'),
(10, 'tizlatin.webp', 'ⵜⵉⵣⵍⴰⵜⵉⵏ ⵉⵏⵓ', 'ⵜⵉⵣⵍⴰⵜⵉⵏ_ⵉⵏⵓ', '<p>    ⵜⵉⵣⵍⴰⵜⵉⵏ ⵉⵏⵓ أو قصائدي، هي مجموعة من الأناشيد الجميلة للأطفال باللغة الأمازيغية، من شأنها تطوير رصيدهم اللغوي وتشجيعهم على المطالعة بالأمازيغية. </p>                                           ', 'ⵜⵉⵣⵍⴰⵜⵉⵏ ⵉⵏⵓ أو قصائدي، هي مجموعة من الأناشيد الجميلة للأطفال باللغة الأمازيغية، من شأنها تطوير رصيدهم اللغوي وتشجيعهم على المطالعة بالأمازيغية.', 'ⵜⵉⵣⵍⴰⵜⵉⵏ ⵉⵏⵓ أو قصائدي، هي مجموعة من الأناشيد الجميلة للأطفال باللغة الأمازيغية، من شأنها تطوير رصيدهم اللغوي وتشجيعهم على المطالعة بالأمازيغية.', '', 'tizlatin.pdf', 'قصائد شعرية, الأمازيغيةالأمازيغية', 'rtl', 'amz', 'public', '2025-09-08 23:08:14', '2024-08-20 23:00:00', 'female', 2, 75, '0'),
(33, 'tirah.webp', 'ⵜⵉⵔⴰ - كتاب لتعلم الكتابة بأحرف تيفيناغ', 'ⵜⵉⵔⴰ_كتاب_لتعلم_الكتابة_بأحرف_تيفيناغ', 'كتاب ⵜⵉⵔⴰ يهدف لتعليم الكتابة بأحرف تيفيناغ، ينصح بتحميله بصيغة pdf ثم طباعته على الورق لمن يرغب في تحسين خط أثناء الكتابة بالأحرف الأمازيغية تيفيناغ.							', 'كتاب ⵜⵉⵔⴰ يهدف لتعليم الكتابة بأحرف تيفيناغ، ينصح بتحميله بصيغة pdf ثم طباعته على الورق لمن يرغب في تحسين خط أثناء الكتابة بالأحرف الأمازيغية تيفيناغ.						', 'كتاب ⵜⵉⵔⴰ يهدف لتعليم الكتابة بأحرف تيفيناغ، ينصح بتحميله بصيغة pdf ثم طباعته على الورق لمن يرغب في تحسين خط أثناء الكتابة بالأحرف الأمازيغية تيفيناغ.						', 'حميد بعلوان', 'tira.pdf', 'الأمازيغية', 'rtl', 'amz', 'public', '2025-09-08 23:08:14', '2024-09-09 23:00:00', 'all', 5, 75, '0'),
(34, 'francais1.webp', 'Le français en images', 'Le_français_en_images', 'Vocabulaire : Une centaine de mots imagés pour trouver facilement celui que tu cherches. • Grammaire: Les règles de base du français. ', 'Vocabulaire : Une centaine de mots imagés pour trouver facilement celui que tu cherches. • Grammaire: Les règles de base du français. ', 'Vocabulaire : Une centaine de mots imagés pour trouver facilement celui que tu cherches. • Grammaire: Les règles de base du français. ', '', 'Le français en images.pdf', 'Apprendre le français, القواميس اللغوية - Dictionaries', 'ltr', 'Fr', 'public', '2025-09-08 23:08:14', '2024-08-20 23:00:00', 'all', 2, 75, '0'),
(35, 'francais2.webp', 'Dictionnaire illustre', 'Dictionnaire_illustre', 'Mon premier dictionnaire francais en images. Mon premier dictionnaire anglais-français. Mon Premier Dictionnaire Bilingue Français-anglais.', 'Mon premier dictionnaire francais en images. Mon premier dictionnaire anglais-français. Mon Premier Dictionnaire Bilingue Français-anglais.', 'Mon premier dictionnaire francais en images. Mon premier dictionnaire anglais-français. Mon Premier Dictionnaire Bilingue Français-anglais.', '', 'Fp_FLS_dictionnaire_illustre_eli_junior-4.pdf', 'Apprendre le français, القواميس اللغوية - Dictionaries', 'ltr', 'Fr', 'public', '2025-09-08 23:08:14', '2024-08-20 23:00:00', 'all', 2, 75, '0'),
(36, 'English1.webp', 'Dictionnaire visuel bilingue français Anglais', 'Dictionnaire_visuel_bilingue_français_Anglais', 'Une fois que vous serez plus sûr de vous, choisissez des mots dans l\'index de la langue étrangère et essayez de voir si vous en connaissez le sens ', 'Une fois que vous serez plus sûr de vous, choisissez des mots dans l\'index de la langue étrangère et essayez de voir si vous en connaissez le sens ', 'Une fois que vous serez plus sûr de vous, choisissez des mots dans l\'index de la langue étrangère et essayez de voir si vous en connaissez le sens ', '', 'Dictionnaire visuel bilingue français Anglais.pdf', 'Learn English, القواميس اللغوية - Dictionaries, الانجليزية', 'ltr', 'En', 'public', '2025-09-08 23:08:14', '2024-08-20 23:00:00', 'all', 2, 75, '0'),
(37, 'francais3.webp', 'Le grand dictionnaire en images', 'Le_grand_dictionnaire_en_images', 'Cette édition numérique a été fabriquée par la société FeniXX au format PDF. La couverture reproduit celle du livre original conservé au sein des collections ', 'Cette édition numérique a été fabriquée par la société FeniXX au format PDF. La couverture reproduit celle du livre original conservé au sein des collections ', 'Cette édition numérique a été fabriquée par la société FeniXX au format PDF. La couverture reproduit celle du livre original conservé au sein des collections ', '', '9782307525912.pdf', 'Apprendre le français, القواميس اللغوية - Dictionaries', 'ltr', 'Fr', 'public', '2025-09-08 23:08:14', '2024-08-20 23:00:00', 'all', 2, 75, '0'),
(38, 'SVT1.webp', ' Découverte d’un milieu naturel-Cours-1-Word', 'Découverte_d_un_milieu_naturel_Cours_1_Word', '•	Dans la nature, il existe de nombreux endroits différents :  la foret, les rivières, la mer, la plage, l’étang, le lac…', '•	Dans la nature, il existe de nombreux endroits différents :  la foret, les rivières, la mer, la plage, l’étang, le lac…', '•	Dans la nature, il existe de nombreux endroits différents :  la foret, les rivières, la mer, la plage, l’étang, le lac…', '', 'Decouverte-dun-milieu-naturel-Cours-1-Word.docx', 'SVT,علوم الحياة والأرض', 'ltr', 'Fr', 'public', '2025-09-08 23:11:17', '2024-08-20 23:00:00', 'all', 9, 75, '4'),
